/** Storage object paths are generated by us, but validate anyway: no traversal, no surprises. */
export function assertSafeStoragePath(path: string): string {
  if (!/^[A-Za-z0-9][A-Za-z0-9/_.-]{0,200}$/.test(path) || path.includes("..") || path.includes("//") || path.endsWith("/")) {
    throw new Error("unsafe storage path");
  }
  return path;
}
